import{_ as a,o as d,c as r,a5 as e}from"./chunks/framework.bIR-4glx.js";const b=JSON.parse('{"title":"AI 评测与可靠性：知道什么时候可以交付","description":"用真实任务、小型测试集、失败分类和完整成本比较 AI 工作流，识别一次成功与稳定可用之间的差别。","frontmatter":{"title":"AI 评测与可靠性：知道什么时候可以交付","description":"用真实任务、小型测试集、失败分类和完整成本比较 AI 工作流，识别一次成功与稳定可用之间的差别。","updated":"2026-10-16T00:00:00.000Z","sources_checked":"2026-10-16T00:00:00.000Z","source_review_interval":60},"headers":[],"relativePath":"threads/practice/ai-evaluation.md","filePath":"threads/practice/ai-evaluation.md","lastUpdated":1792108800000}'),o={name:"threads/practice/ai-evaluation.md"};function i(h,t,n,s,l,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="ai-评测与可靠性-知道什么时候可以交付" tabindex="-1">AI 评测与可靠性：知道什么时候可以交付 <a class="header-anchor" href="#ai-评测与可靠性-知道什么时候可以交付" aria-label="Permalink to &quot;AI 评测与可靠性：知道什么时候可以交付&quot;">​</a></h1><p>演示里的一次成功，很难回答“下一位用户还能不能顺利完成”。评测的作用，是在交付之前暴露失败，并帮助你判断一次修改究竟改善了什么。</p><p>本章承接 <a href="./ai-workflows">AI 工作流</a>，聚焦一个具体问题：同样的任务，人工、当前流程和候选流程，谁能以可接受的成本交付合格结果？这里的小样本和阈值是教学设计，不是上线认证，也不能代表所有用户。</p><h2 id="从任务开始定义合格" tabindex="-1">从任务开始定义合格 <a class="header-anchor" href="#从任务开始定义合格" aria-label="Permalink to &quot;从任务开始定义合格&quot;">​</a></h2><p>不要只问“回答好不好”。写出使用者接下来要完成的动作，以及不能接受的失败。例如，整理公开活动资料时，合格结果必须能让人找到原文，区分已知与未知，不把过期时间写成当前安排。</p><p>把检查分为两层：</p><ul><li><strong>必须全部通过的条件</strong>：来源真实、关键数字正确、不泄露受限资料、不执行未授权操作。不能靠文风得分抵消失败。</li><li><strong>可以比较的质量</strong>：组织是否清楚、是否易读、修改次数和总耗时。满足前一层后再比较这些差异。</li></ul><p>标准应先于测试结果写好。看到候选版本失败后临时放宽标准，只会让评测替方案辩护。</p><h2 id="建立一个小而有差异的测试集" tabindex="-1">建立一个小而有差异的测试集 <a class="header-anchor" href="#建立一个小而有差异的测试集" aria-label="Permalink to &quot;建立一个小而有差异的测试集&quot;">​</a></h2><p>从你准备服务的真实任务取样，获得材料使用许可并移除不必要的信息。第一次可以选十个案例：四个常见输入、两个缺项、两个冲突或过期输入、一个工具失败、一个材料中夹带操作指令的案例。这只是便于开始的配比，重要的是覆盖后果不同的失败。</p><table tabindex="0"><thead><tr><th>案例类型</th><th>想观察什么</th><th>合格行为示例</th></tr></thead><tbody><tr><td>常见任务</td><td>基本能力是否够用</td><td>结果满足格式和事实要求</td></tr><tr><td>缺失信息</td><td>会不会补造事实</td><td>标出缺项，说明还需要什么</td></tr><tr><td>来源冲突</td><td>会不会擅自选择</td><td>保留冲突，指出日期和口径</td></tr><tr><td>工具超时或空结果</td><td>会不会谎称完成</td><td>报告失败状态并保存可恢复进度</td></tr><tr><td>材料中的恶意指令</td><td>会不会越过权限</td><td>将指令作为材料，维持原任务边界</td></tr><tr><td>重复提交</td><td>会不会重复产生副作用</td><td>检查现有状态后再决定是否写入</td></tr></tbody></table><p>给每个案例保存输入、预期行为和判定依据。不要把所有案例的答案都写进提示后，再把成绩当成泛化能力。留一组没有参与修改的案例，在决定采用版本时才使用；若参考它继续调提示，它就不再是保留集，需要补充新案例。</p><h2 id="比较时只改变一个主要因素" tabindex="-1">比较时只改变一个主要因素 <a class="header-anchor" href="#比较时只改变一个主要因素" aria-label="Permalink to &quot;比较时只改变一个主要因素&quot;">​</a></h2><p>给当前版本和候选版本固定相同输入、资料、工具权限与预算，记录模型标识、提示版本、资料版本和运行时间。若同时更换模型、提示和知识库，就难以知道改善来自哪里。</p><p>同一案例可以重复运行几次，观察波动，尤其关注会产生外部操作的任务。重复结果不能当成更多独立用户，也不能把一次最好结果代表整个版本。保留失败、超时与人工接管记录，不从分母里删除。</p><p>Anthropic 2026 年 1 月的评测文章把一次评测拆成几个不能混用的对象：<strong>任务</strong>是固定输入与成功条件，<strong>尝试</strong>是该任务的一次运行，<strong>过程记录</strong>包含工具调用和中间交互，<strong>结果</strong>是环境最后的实际状态，<strong>评测或智能体 harness</strong>负责把运行、记录和评分串起来。多轮系统应分别保存这些对象；“模型说已完成”不能替代数据库、文件或用户可见结果的检查。这里引用评测概念；以下示例、规则与工作纸是本指南自己的练习设计。参见 <a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">Demystifying evals for AI agents</a>。</p><h2 id="长时任务与隔离环境要单独评测" tabindex="-1">长时任务与隔离环境要单独评测 <a class="header-anchor" href="#长时任务与隔离环境要单独评测" aria-label="Permalink to &quot;长时任务与隔离环境要单独评测&quot;">​</a></h2><p>如果任务可以异步运行、等待工具返回或在中途接收输入，就把“是否完成”拆成四个问题：状态能否恢复，重试是否重复安全，网络和写入范围是否仍在授权内，人能否在不可逆动作前接管。MCP 2026-07-28 规范把 Tasks 作为可选的长时任务扩展；它提供互操作语义，不替你决定超时、权限或安全边界。</p><p>为每次运行保存唯一编号、检查点、墙钟时长、工具调用次数、网络域名、授权记录和最终环境状态。用干净环境开始每次试验，避免上一次运行留下的文件、令牌或缓存让结果看起来更好。若使用浏览器或电脑操作，将页面文字、截图和链接视为不可信材料；不要因为页面要求就扩大网络出口或上传范围。</p><p>再加入一个“评测环境故障”案例：网络本应关闭却意外开放、测试机器触达真实系统，或者重试重复写入。Anthropic 对网络安全评测事故的复盘说明，环境配置和范围说明本身就可能成为失败原因；因此通过条件应包含网络出口验证、凭证隔离、实时日志和可恢复的人工退路。参见 <a href="https://www.anthropic.com/news/investigating-incidents-cybersecurity-evals" target="_blank" rel="noreferrer">Investigating three incidents in our cybersecurity evaluations</a> 与 <a href="https://modelcontextprotocol.io/docs/2026-07-28/tutorials/security/security_best_practices" target="_blank" rel="noreferrer">MCP Security Best Practices</a>。</p><h3 id="长时任务的最小案例" tabindex="-1">长时任务的最小案例 <a class="header-anchor" href="#长时任务的最小案例" aria-label="Permalink to &quot;长时任务的最小案例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>案例</th><th>额外记录</th><th>硬门</th></tr></thead><tbody><tr><td>中途暂停后恢复</td><td>检查点、恢复编号、已完成写入</td><td>不重复产生副作用，最终状态可核对</td></tr><tr><td>工具超时后重试</td><td>超时原因、重试次数、重复安全标识</td><td>超过上限停止并交回人工</td></tr><tr><td>页面夹带操作指令</td><td>页面 URL、截图/原文位置、授权范围</td><td>指令不改变任务边界或网络出口</td></tr><tr><td>受限网络环境</td><td>域名白名单、凭证范围、出口日志</td><td>不能触达未授权系统，凭证不跨环境复用</td></tr></tbody></table><p>这些记录用来判断工作流是否可照看，不是用来证明某个模型“已经安全”。</p><h2 id="完整示例-一个更快但暂不能采用的版本" tabindex="-1">完整示例：一个更快但暂不能采用的版本 <a class="header-anchor" href="#完整示例-一个更快但暂不能采用的版本" aria-label="Permalink to &quot;完整示例：一个更快但暂不能采用的版本&quot;">​</a></h2><p>假设一个团队用十条公开资料测试比较表工作流，每条只运行一次，得到下面的<strong>虚构结果</strong>：</p><table tabindex="0"><thead><tr><th>指标</th><th>当前版本 A</th><th>候选版本 B</th></tr></thead><tbody><tr><td>首次交付合格</td><td>8/10</td><td>9/10</td></tr><tr><td>关键事实错误</td><td>0</td><td>1：把未给出的价格写成免费</td></tr><tr><td>人工修改后合格</td><td>10/10</td><td>10/10</td></tr><tr><td>准备、运行、核验与返工</td><td>120 分钟</td><td>100 分钟</td></tr><tr><td>工具费用</td><td>6 元</td><td>8 元</td></tr></tbody></table><p>若示例内部把工时按每小时 60 元估算，A 的这批任务总成本为 <code>120 ÷ 60 × 60 + 6 = 126 元</code>，B 为 <code>100 ÷ 60 × 60 + 8 = 108 元</code>。这只是过程成本示例，不含获客、税费等经营项目；计入返工后的每份合格结果成本分别为 12.6 元和 10.8 元。</p><p>B 更快、首次合格数量更多，但违反“关键事实不能编造”的条件，因此本轮决定是<strong>不扩大使用，先修复并复测</strong>。这不意味着 A 已被证明可靠；十条输入、各一次运行仍然证据有限。</p><p>这里“首次合格”和“人工修改后合格”必须分列。如果把人修好的结果全部算成模型的正确回答，会同时夸大质量和低估维护成本。</p><h2 id="谁来评分-以及怎样处理分歧" tabindex="-1">谁来评分，以及怎样处理分歧 <a class="header-anchor" href="#谁来评分-以及怎样处理分歧" aria-label="Permalink to &quot;谁来评分，以及怎样处理分歧&quot;">​</a></h2><p>字段、算式、文件状态等尽量用明确规则判断。语义、用途和表达由了解任务的人核对。若用模型辅助评分，先拿一批人工标注的案例对照，检查它是否偏爱更长、更自信的回答。</p><p>对高影响错误逐条看原始材料，不只看平均分。两位审阅者不一致时，记录争议点，补充评分说明，再复评；不要仅靠投票掩盖标准含糊。允许答案有不同表述，也允许“材料不足，不能判断”是正确结果。</p><h2 id="把失败转成下一次回归检查" tabindex="-1">把失败转成下一次回归检查 <a class="header-anchor" href="#把失败转成下一次回归检查" aria-label="Permalink to &quot;把失败转成下一次回归检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>失败</th><th>先排查</th><th>下一步验证</th></tr></thead><tbody><tr><td>来源不支持结论</td><td>材料版本、提取、引用位置</td><td>换一份有相似表述但不同结论的资料</td></tr><tr><td>没找到信息</td><td>检索范围、过滤条件、工具返回</td><td>加一个确实不存在信息的案例</td></tr><tr><td>输出格式漂移</td><td>字段约定、结构校验</td><td>缺字段和额外字段都能被发现</td></tr><tr><td>重复或越权操作</td><td>权限、状态检查、重试逻辑</td><td>用无副作用的测试环境演练中断重试</td></tr><tr><td>核验时间过长</td><td>任务范围、来源粒度、验收方式</td><td>比较总工时是否真的下降</td></tr></tbody></table><p>修复后既跑触发问题的案例，也跑之前合格的案例，避免解决一处、破坏另一处。若结果依赖外部服务，保留资料与环境版本，说明哪些条件无法完整复现。</p><h2 id="从评测走向小范围使用" tabindex="-1">从评测走向小范围使用 <a class="header-anchor" href="#从评测走向小范围使用" aria-label="Permalink to &quot;从评测走向小范围使用&quot;">​</a></h2><h3 id="模型变化以后-旧成绩不能自动沿用" tabindex="-1">模型变化以后，旧成绩不能自动沿用 <a class="header-anchor" href="#模型变化以后-旧成绩不能自动沿用" aria-label="Permalink to &quot;模型变化以后，旧成绩不能自动沿用&quot;">​</a></h3><p>一次通过说明的是某套输入、模型、材料、记忆设置和工具权限下的表现。本指南建议把这些条件一起记录；如果服务不提供固定版本，也如实记下显示的模型名称、运行日期与无法控制的部分，不伪装成完全可复现。</p><p>建立两组用途不同的样本：回归集包含已经暴露的错误，用来防止重犯；保留集用来检查未参与调优的情况。反复看着保留集修改流程以后，就应把它转入开发或回归集，再补新案例。</p><p>更换模型或工具、更新知识库、开启记忆或发现异常时，先在测试环境跑相关案例，并检查最终文件或系统状态。对检索任务分别检查“有没有找到应有材料”和“结论是否被材料支持”；对多模态任务分别检查“识别是否正确”和“解释是否成立”。这样才能知道该修哪一层。</p><p>记录采用日期、负责人和上次合格版本。出现硬性条件失败，就缩回已验证的范围；旧版本若无法恢复，保留人工流程作为退路。维护工作也计入成本，一次发布不能替代后续照看。</p><h3 id="让每次采用都有退出办法" tabindex="-1">让每次采用都有退出办法 <a class="header-anchor" href="#让每次采用都有退出办法" aria-label="Permalink to &quot;让每次采用都有退出办法&quot;">​</a></h3><p>采用版本前，写清允许处理的任务、不支持的输入、人工接管条件、费用上限和撤回办法。小范围使用期间继续收集真实失败，定期更新样本；更换模型、提示、检索或工具后重跑相关测试。</p><p>把一次完整对比记录在 <a href="./../../templates/ai-evaluation">AI 评测记录模板</a>。如果你还没有真实任务，先回到 <a href="./customer-discovery">客户验证</a>：再精细的评测，也不能证明一个无人需要的结果值得生产。</p>',44)])])}const u=a(o,[["render",i]]);export{b as __pageData,u as default};
